function openJournal(chunks) {
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  let iterator;
  let closed = false;
  let sourceDone = false;
  let returnPromise;
  let chunk = null;
  let offset = 0;
  let line = 0;

  function release() {
    if (returnPromise) return returnPromise;
    if (!iterator || sourceDone) return Promise.resolve();

    returnPromise = Promise.resolve().then(async () => {
      const method = iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    });
    return returnPromise;
  }

  function done() {
    return { done: true, value: undefined };
  }

  function eventFor(text) {
    const currentLine = ++line;
    if (text.trim() === "") return undefined;

    try {
      return {
        line: currentLine,
        ok: true,
        value: JSON.parse(text)
      };
    } catch {
      return { line: currentLine, ok: false, text };
    }
  }

  async function next() {
    if (closed) return done();

    const parts = [];
    let hasBytes = false;

    try {
      if (!iterator) {
        iterator = chunks[Symbol.asyncIterator]();
      }

      while (!closed) {
        if (chunk === null || offset === chunk.length) {
          chunk = null;
          offset = 0;

          const result = await iterator.next();
          if (closed) return done();

          if (result.done) {
            sourceDone = true;
            closed = true;

            const tail = decoder.decode();
            if (tail) parts.push(tail);

            if (!hasBytes) return done();

            const event = eventFor(parts.join(""));
            return event === undefined
              ? done()
              : { done: false, value: event };
          }

          chunk = result.value;
          if (chunk.length === 0) continue;
        }

        let end = offset;
        while (end < chunk.length && chunk[end] !== 0x0a) {
          end++;
        }

        if (end > offset) {
          hasBytes = true;
          const text = decoder.decode(chunk.subarray(offset, end), {
            stream: true
          });
          if (text) parts.push(text);
        }

        if (end === chunk.length) {
          offset = end;
          continue;
        }

        offset = end + 1;
        const tail = decoder.decode();
        if (tail) parts.push(tail);

        let text = parts.join("");
        parts.length = 0;
        hasBytes = false;

        if (text.endsWith("\r")) {
          text = text.slice(0, -1);
        }

        const event = eventFor(text);
        if (event !== undefined) {
          return { done: false, value: event };
        }
      }

      return done();
    } catch (error) {
      closed = true;
      chunk = null;
      offset = 0;

      try {
        await release();
      } catch {
        // Preserve the original reading error.
      }

      throw error;
    }
  }

  async function close() {
    closed = true;
    chunk = null;
    offset = 0;
    await release();
  }

  return { next, close };
}
